// Secret: set once in this node's 'secret' env/context — never in the URL.
const crypto = global.get('crypto') || require('crypto');
const SECRET = env.get('LORISIOT_WEBHOOK_SECRET') || flow.get('lorisiot_secret');
const REPLAY_WINDOW_S = 300;
const DEDUPE_CAP = 1000;

if (!SECRET) { msg.statusCode = 500; msg.payload = { error: 'secret not configured' }; return [null, msg]; }

// 1. Signature — recompute over the RAW body and constant-time compare.
const raw = msg.req.rawBody !== undefined ? msg.req.rawBody : JSON.stringify(msg.payload);
const expected = 'sha256=' + crypto.createHmac('sha256', SECRET).update(raw).digest('hex');
const given = msg.req.headers['x-lorisiot-signature'] || '';
const ok = given.length === expected.length && crypto.timingSafeEqual(Buffer.from(given), Buffer.from(expected));
if (!ok) { msg.statusCode = 401; msg.payload = { error: 'bad signature' }; return [null, msg]; }

const body = msg.payload;

// 2. Replay window on ts.
const now = Math.floor(Date.now() / 1000);
if (typeof body.ts !== 'number' || Math.abs(now - body.ts) > REPLAY_WINDOW_S) {
    msg.statusCode = 403; msg.payload = { error: 'stale timestamp' }; return [null, msg];
}

// 3. eventId dedupe — a retried POST must not double-fire.
const seen = context.get('seenEventIds') || [];
if (seen.includes(body.eventId)) {
    msg.statusCode = 200; msg.payload = { duplicate: true }; return [null, msg];
}
seen.push(body.eventId);
if (seen.length > DEDUPE_CAP) seen.splice(0, seen.length - DEDUPE_CAP);
context.set('seenEventIds', seen);

// 4. Version gate — branch on v, never guess an unknown contract.
if (body.v !== 1) { msg.statusCode = 400; msg.payload = { error: 'unsupported contract version ' + body.v }; return [null, msg]; }

msg.statusCode = 200;
return [msg, null];
